INSERT INTO skill (id, title, description, "categoryId", "ownerId", "createdAt", "updatedAt") VALUES
('40000000-0000-0000-0000-000000000001', 'Разработка сайтов на React', 'Помогу освоить React, Redux, Next.js. Научу создавать современные веб-приложения.', '20000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001', NOW(), NOW()),
('40000000-0000-0000-0000-000000000002', 'Создание логотипов в Adobe Illustrator', 'Научу основам работы в Illustrator, созданию векторной графики и логотипов.', '20000000-0000-0000-0000-000000000006', '30000000-0000-0000-0000-000000000002', NOW(), NOW()),
('40000000-0000-0000-0000-000000000003', 'Продвижение в Instagram', 'Расскажу, как создавать контент, привлекать подписчиков и настраивать рекламу в Instagram.', '20000000-0000-0000-0000-000000000008', '30000000-0000-0000-0000-000000000004', NOW(), NOW()),
('40000000-0000-0000-0000-000000000004', 'Обработка фотографий в Lightroom', 'Покажу, как улучшить ваши фотографии с помощью Adobe Lightroom. Цветокоррекция, ретушь и многое другое.', '20000000-0000-0000-0000-000000000011', '30000000-0000-0000-0000-000000000005', NOW(), NOW()),
('40000000-0000-0000-0000-000000000005', 'Разработка мобильных приложений на Flutter', 'Научу создавать кроссплатформенные мобильные приложения для iOS и Android с помощью фреймворка Flutter.', '20000000-0000-0000-0000-000000000002', '30000000-0000-0000-0000-000000000003', NOW(), NOW()),
('40000000-0000-0000-0000-000000000006', 'Настройка контекстной рекламы в Яндекс.Директ', 'Помогу разобраться в настройке и ведении рекламных кампаний в Яндекс.Директ. Сбор семантики, написание объявлений, аналитика.', '20000000-0000-0000-0000-000000000009', '30000000-0000-0000-0000-000000000004', NOW(), NOW());
